  $sepjson${"slug": "sport-and-exercise-psychology", "title": "Sport and Exercise Psychology", "description": "This course examines psychological factors in sport, exercise, performance, coaching, physical activity, and well-being. Students study motivation, personality, identity, arousal, stress, anxiety, confidence, resilience, goal setting, behavior change, imagery, self-talk, attention, concentration, flow, mindfulness, group dynamics, leadership, exercise adherence, mental health, burnout, injury rehabilitation, return to play, diversity, ethics, evidence, and applied consultation.", "topics": [{"id": "24544d3b-8d8a-48c3-9b25-85f660f2226c", "type": "topic", "title": "Foundations, Scope, Ethics, and Evidence in Sport and Exercise Psychology", "description": "Establish what the field studies, how evidence is used, and where ethical boundaries sit.", "children": [{"id": "23f6a140-42a2-421f-be0e-ac2603ee513b", "type": "subtopic", "title": "Field scope", "description": "Students learn what sport and exercise psychology can explain and where other professions are needed.", "children": [{"id": "106e572a-9f85-4b34-abef-54acfa23cbce", "type": "concept", "title": "Performance psychology"}, {"id": "5dbb57c8-50d7-4cd6-9f16-bdd3a79b9dde", "type": "concept", "title": "Exercise behavior"}, {"id": "8eb18e94-c4fb-46e4-ac39-58386cc50418", "type": "concept", "title": "Mental health intersections"}, {"id": "cf8a543a-3627-43d3-a0f3-927cb632018f", "type": "concept", "title": "Research and applied practice"}]}, {"id": "916e82fc-e529-467c-9790-c5d61b78c706", "type": "subtopic", "title": "Evidence and methods", "description": "Students learn to treat mental skills and behavior-change claims with evidence-based discipline.", "children": [{"id": "6b118c09-3e76-4da7-81aa-70123f66236b", "type": "concept", "title": "Experimental designs"}, {"id": "cd5238ad-3c54-47ea-95eb-b0ec3811d867", "type": "concept", "title": "Qualitative methods"}, {"id": "394d95d5-891a-4a2b-8aeb-12e5e24e856e", "type": "concept", "title": "Measurement validity"}, {"id": "fc77cb87-b2e2-448a-a007-9f8ac7be4e73", "type": "concept", "title": "Applied case evidence"}]}, {"id": "37e065d7-3ffc-48ad-afcd-0dbd0ead1313", "type": "subtopic", "title": "Ethics and boundaries", "description": "Students distinguish education and performance support from diagnosis or therapy.", "children": [{"id": "e9467470-1a94-4568-a1be-d78e9484cad3", "type": "concept", "title": "Informed consent"}, {"id": "43da3a71-a9f1-4b5e-afb0-089202e56949", "type": "concept", "title": "Confidentiality"}, {"id": "e65068bf-c07d-4084-a94a-a1a6248c39cc", "type": "concept", "title": "Scope of practice"}, {"id": "98402d8e-eedc-45b1-8467-0c6abd69abb2", "type": "concept", "title": "Referral pathways"}]}]}, {"id": "5b1f6798-0e40-41e2-9fe9-2260e238281f", "type": "topic", "title": "Personality, Individual Differences, and Athlete Identity", "description": "Explore how traits, identity, culture, and development shape sport and exercise experiences.", "children": [{"id": "14877cab-243e-4050-a9c9-4c2214f6fd63", "type": "subtopic", "title": "Personality in sport", "description": "Students examine how traits may relate to sport participation without overusing labels.", "children": [{"id": "699cc7d6-fdb6-4fb8-8ba7-26b65c574531", "type": "concept", "title": "Trait perspectives"}, {"id": "8549f964-b163-4831-87e0-5e0fdb45f429", "type": "concept", "title": "Big Five concepts"}, {"id": "f0374fb5-bfea-4032-9f9d-275ed5c5d9a0", "type": "concept", "title": "Competitive orientation"}, {"id": "edb8a9b7-1c97-4d32-9749-92341c925c9c", "type": "concept", "title": "Limits of prediction"}]}, {"id": "09d585d4-4829-4e53-a6f0-42cc9f040fca", "type": "subtopic", "title": "Athlete and exerciser identity", "description": "Identity can motivate participation but also create vulnerability during injury, burnout, or transition.", "children": [{"id": "6cca8ef6-fe3d-4955-8455-cf56939b0e0d", "type": "concept", "title": "Athletic identity"}, {"id": "17238bb6-d85c-4969-9