an.", "children": [{"id": "24ed0d8a-fbdf-46a2-bc90-5b44d69f28a4", "type": "concept", "title": "Referral question"}, {"id": "c7c15261-8a08-46ef-bcc0-c0b791b54999", "type": "concept", "title": "Needs assessment"}, {"id": "aeec5848-9bbc-4a9c-8c7e-7fdf1a2a564e", "type": "concept", "title": "Strengths and barriers"}, {"id": "74f80b97-76cb-4790-826c-a9e1416adf0b", "type": "concept", "title": "Intervention rationale"}]}, {"id": "c38db815-c11f-4927-84d5-fd277f77a79f", "type": "subtopic", "title": "Diversity-responsive practice", "description": "Applied psychology must fit the person, setting, and culture.", "children": [{"id": "67bb7338-d744-426e-b36f-1607fdb3afe1", "type": "concept", "title": "Cultural humility"}, {"id": "57354a81-be87-4c69-8c8b-6dc9c0d4b6fb", "type": "concept", "title": "Language and accessibility"}, {"id": "3993811a-7e8c-4edc-a271-ba6589d2baf7", "type": "concept", "title": "Trauma-informed awareness"}, {"id": "59b6950d-5c8e-4e94-b990-b7ef6ca917f2", "type": "concept", "title": "Power dynamics"}]}, {"id": "8a12fd2a-f0d3-4093-86df-7bb22b7d9a20", "type": "subtopic", "title": "Professional communication", "description": "Students learn to present recommendations clearly and ethically.", "children": [{"id": "792ed48c-b4f7-47c2-9ae4-6b6819ab10d4", "type": "concept", "title": "Plain-language explanations"}, {"id": "5245141b-3cc8-4f1e-80bd-fa6c0b1643e3", "type": "concept", "title": "Coach/parent/team communication"}, {"id": "8aabec4c-d35f-402e-92eb-3956e42b0817", "type": "concept", "title": "Confidentiality limits"}, {"id": "ba78c2d8-d288-4ec6-ad5f-e2d1cb399bbf", "type": "concept", "title": "Evaluation and follow-up"}]}]}], "dbBacked": true}$sepjson$::jsonb,
