set
  title = 'Sport and Exercise Psychology',
  goal = 'Sport and Exercise Psychology',
  summary = 'This course examines psychological factors in sport, exercise, performance, coaching, physical activity, and well-being. Students study motivation, personality, identity, arousal, stress, anxiety, confidence, resilience, goal setting, behavior change, imagery, self-talk, attention, concentration, flow, mindfulness, group dynamics, leadership, exercise adherence, mental health, burnout, injury rehabilitation, return to play, diversity, ethics, evidence, and applied consultation.',
  data = $sepjson${"slug": "sport-and-exercise-psychology", "title": "Sport and Exercise Psychology", "description": "This course examines psychological factors in sport, exercise, performance, coaching, physical activity, and well-being. Students study motivation, personality, identity, arousal, stress, anxiety, confidence, resilience, goal setting, behavior change, imagery, self-talk, attention, concentration, flow, mindfulness, group dynamics, leadership, exercise adherence, mental health, burnout, injury rehabilitation, return to play, diversity, ethics, evidence, and applied consultation.", "topics": [{"id": "24544d3b-8d8a-48c3-9b25-85f660f2226c", "type": "topic", "title": "Foundations, Scope, Ethics, and Evidence in Sport and Exercise Psychology", "description": "Establish what the field studies, how evidence is used, and where ethical boundaries sit.", "children": [{"id": "23f6a140-42a2-421f-be0e-ac2603ee513b", "type": "subtopic", "title": "Field scope", "description": "Students learn what sport and exercise psychology can explain and where other professions are needed.", "children": [{"id": "106e572a-9f85-4b34-abef-54acfa23cbce", "type": "concept", "title": "Performance psychology"}, {"id": "5dbb57c8-50d7-4cd6-9f16-bdd3a79b9dde", "type": "concept", "title": "Exercise behavior"}, {"id": "8eb18e94-c4fb-46e4-ac39-58386cc50418", "type": "concept", "title": "Mental health intersections"}, {"id": "cf8a543a-3627-43d3-a0f3-927cb632018f", "type": "concept", "title": "Research and applied practice"}]}, {"id": "916e82fc-e529-467c-9790-c5d61b78c706", "type": "subtopic", "title": "Evidence and methods", "description": "Students learn to treat mental skills and behavior-change claims with evidence-based discipline.", "children": [{"id": "6b118c09-3e76-4da7-81aa-70123f66236b", "type": "concept", "title": "Experimental designs"}, {"id": "cd5238ad-3c54-47ea-95eb-b0ec3811d867", "type": "concept", "title": "Qualitative methods"}, {"id": "394d95d5-891a-4a2b-8aeb-12e5e24e856e", 